INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(7101, '1 Samuel 16:13', '1 Samuel', 16, 13, '&nbsp;سموئيل د زيتُونو هغه تېل واخستل چې د ګډ په ښکر کښې وُو او د داؤد سر يې د هغۀ د وروڼو په مخکښې غوړ کړو. د مالِک خُدائ روح ناڅاپه د طاقت سره په داؤد نازل شو او د هغې ورځې نه د هغۀ سره شو. بيا سموئيل واپس راما ته لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7102, '1 Samuel 16:14', '1 Samuel', 16, 14, '&nbsp;د مالِک خُدائ روح د ساؤل نه لاړو او د مالِک خُدائ رالېږلے شوى پېرى هغه ونيولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7103, '1 Samuel 16:15', '1 Samuel', 16, 15, '&nbsp;د هغۀ نوکرانو هغۀ ته ووئيل، ”مونږ ته پته ده چې تۀ د مالِک خُدائ رالېږلے شوى پېرى نيولے يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7104, '1 Samuel 16:16', '1 Samuel', 16, 16, '&nbsp;نو صاحِبه، مونږ له حُکم راکړه چې مونږ داسې سړے ولټوُو چې هغه رباب غږولے شى. بيا چې کله هغه پېرى په تا راشى، نو هغه سړے به بينجو وغږوى او تۀ به ټيک شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7105, '1 Samuel 16:17', '1 Samuel', 16, 17, '&nbsp;ساؤل هغوئ له حُکم ورکړو، ”ما له يو داسې سړے ولټوئ چې هغه بينجو ښۀ غږولے شى او ما له يې راولئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7106, '1 Samuel 16:18', '1 Samuel', 16, 18, '&nbsp;يو نوکر يې ووئيل، ”د بيت‌لحم د ښار، د يَسى يو زوئ دے هغه په موسيقۍ کښې ښۀ ماهِر دے. هغه تکړه او ښائسته سړے دے، هغه يو ښۀ فوجى او تقرير کوونکے دے. مالِک خُدائ د هغۀ مل دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7107, '1 Samuel 16:19', '1 Samuel', 16, 19, '&nbsp;نو ساؤل يَسى ته پېغام وړُونکى ولېږل چې ورته ووائى، ”ما له ستا زوئ داؤد راولېږه، کوم چې د ګډو خيال ساتى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7108, '1 Samuel 16:20', '1 Samuel', 16, 20, '&nbsp;يَسى، ساؤل ته د چېلۍ د يو بچى سره خپل زوئ داؤد ولېږلو، چې ورسره په روټۍ بار کړے خر او يوه د ميو ډکه مشکيزه هم وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7109, '1 Samuel 16:21', '1 Samuel', 16, 21, '&nbsp;داؤد ساؤل له راغلو او د هغۀ خِدمت يې شروع کړو. د ساؤل هغه ډېر خوښ شو او هغه يې خپل د وسلې وړونکے سړے جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7110, '1 Samuel 16:22', '1 Samuel', 16, 22, '&nbsp;بيا ساؤل يَسى ته يو پېغام ولېږلو، ”داؤد زما ډېر خوښ دے. هغه پرېږده چې زما خِدمت کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7111, '1 Samuel 16:23', '1 Samuel', 16, 23, '&nbsp;د هغې وخت نه واخله چې کله به هم د خُدائ پاک رالېږلے شوے پيرے په ساؤل راتلو، نو داؤد به د هغۀ رباب واخستو او ووبه يې غږولو او ساؤل به لږ شان ښۀ شو او ورو ورو به نور هم ښۀ کېدو او پيرے به د هغۀ نه لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7112, '1 Samuel 17:1', '1 Samuel', 17, 1, '&nbsp;فلستيان د يهوداه په ښار شوکه کښې د جنګ دپاره راغونډ شول، هغوئ د شوکه او عزيقه په مينځ کښې په يو ځائ کښې کېمپ ولګولو چې نوم يې اِفس‌دميم وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7113, '1 Samuel 17:2', '1 Samuel', 17, 2, '&nbsp;ساؤل او د بنى اِسرائيلو لښکر د ايله وادۍ سره راغونډ شُو او د فلستيانو خِلاف يې صفونه جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7114, '1 Samuel 17:3', '1 Samuel', 17, 3, '&nbsp;فلستيان په يو غر باندې ودرېدل او بنى اِسرائيليان په بل غر باندې ورته مخامخ ودرېدل، چې د دوئ په مينځ کښې وادى وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7115, '1 Samuel 17:4', '1 Samuel', 17, 4, '&nbsp;بيا د فلستيانو د خېمو نه يو تکړه سړے راووتلو، هغه سړے د جات وو او نوم يې جوليت وو. هغه د درېو ګزو نه لوړ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7116, '1 Samuel 17:5', '1 Samuel', 17, 5, '&nbsp;د هغۀ په سر د زېړو جنګى ټوپۍ وه او د زېړو فوجى زغره يې اغوستې وه چې درې کم شپېتۀ کېلو وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7117, '1 Samuel 17:6', '1 Samuel', 17, 6, '&nbsp;د هغۀ پتُونونه هم د زېړو په زغره باندې پټ وُو او د زېړو نېزه د هغۀ په اوږه باندې ځوړنده وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7118, '1 Samuel 17:7', '1 Samuel', 17, 7, '&nbsp;د هغۀ نېزه د کوټې د تير هومره لويه وه. او د دې د اوسپنې سر تقريباً اووۀ کلو وو. د هغۀ ډال به هغه فوجى وړلو چې د هغۀ نه مخکښې به روان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7119, '1 Samuel 17:8', '1 Samuel', 17, 8, '&nbsp;جوليت ودرېدو او د بنى اِسرائيلو لښکر ته يې چغه وکړه چې، ”تاسو هلته څۀ کوئ، د جنګ دپاره مو صفونه ولې جوړ کړى دى؟ زۀ فلستىے نۀ يم او تاسو د ساؤل نوکران نۀ يئ؟ يو سړے خوښ کړئ چې دلته راشى او زما سره جنګ وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7120, '1 Samuel 17:9', '1 Samuel', 17, 9, '&nbsp;کۀ هغه زما سره جنګ کولے شى او ما ووژنى، نو مونږ به ستاسو غلامان يُو، خو کۀ زۀ يې وګټم او هغه ووژنم، نو تاسو به زمونږ غلامان يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7121, '1 Samuel 17:10', '1 Samuel', 17, 10, '&nbsp;زۀ وايم چې نن د بنى اِسرائيلو په لښکر کښې داسې څوک شته چې زما سره جنګ وکړى ما له داسې سړے راکړئ چې مونږ دواړه جنګ وکړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7122, '1 Samuel 17:11', '1 Samuel', 17, 11, '&nbsp;کله چې ساؤل او د هغۀ سړو دا واورېدل، نو هغوئ زړونه بائيلل او سخت ويرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7123, '1 Samuel 17:12', '1 Samuel', 17, 12, '&nbsp;نو داؤد د يَسى زوئ وو، چې هغه په يهوداه کښې د بيت‌لحم افراتے وو. د يَسى اتۀ زامن وُو او په هغه وخت کښې چې ساؤل بادشاه وو، هغه يو بوډا سړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7124, '1 Samuel 17:13', '1 Samuel', 17, 13, '&nbsp;د هغۀ درې مشران زامن د ساؤل سره جنګ له تلى وُو. د ټولو مشر اِلياب وو، ورپسې ابينداب وو او درېم سِمعه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7125, '1 Samuel 17:14', '1 Samuel', 17, 14, '&nbsp;داؤد يې د ټولو کشر زوئ وو، خو هغه درې مشران وروڼه يې د ساؤل سره کېمپ کښې پاتې کېدل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7126, '1 Samuel 17:15', '1 Samuel', 17, 15, '&nbsp;داؤد به وخت په وخت بيت‌لحم ته تلو راتلو، چې د خپل پلار د ګډو خيال وساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7127, '1 Samuel 17:16', '1 Samuel', 17, 16, '&nbsp;جوليت څلوېښت ورځې هر سحر او ماښام بنى اِسرائيلو ته وئيل چې ما سره جنګ وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7128, '1 Samuel 17:17', '1 Samuel', 17, 17, '&nbsp;يوه ورځ يَسى داؤد ته ووئيل، ”دا لس کلو وريتې دانې او لس روټۍ واخله او زر زر يې کېمپ ته خپلو وروڼو له يوسه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7129, '1 Samuel 17:18', '1 Samuel', 17, 18, '&nbsp;او دا لس پنير مشر آفسر له يوسه. دا معلوم کړه چې ستا وروڼه څنګه دى او چې داسې څۀ نښه راوړې چې د هغې نه دا ښکاره شى چې تا هغوئ وليدل او هغوئ ښۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7130, '1 Samuel 17:19', '1 Samuel', 17, 19, '&nbsp;ساؤل بادشاه، ستا وروڼه او نور ټول بنى اِسرائيليان د ايله په وادۍ کښې دى او د فلستيانو سره جنګ کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7131, '1 Samuel 17:20', '1 Samuel', 17, 20, '&nbsp;داؤد په ورپسې سحر وختى پاڅېدو، بل څوک يې د ګډو ذمه وار پرېښودو، خوراک يې واخستلو او چې څنګه ورته يَسى وئيلى وُو نو هم هغسې لاړو. هغه هم په هغه وخت کېمپ ته ورسېدو چې بنى اِسرائيليان د جنګ دپاره صفونو جوړولو له روان وُو او د جنګ چغې يې وهلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7132, '1 Samuel 17:21', '1 Samuel', 17, 21, '&nbsp;فلستى او بنى اِسرائيلى لښکرو يو بل ته مخامخ د جنګ دپاره صفونه جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7133, '1 Samuel 17:22', '1 Samuel', 17, 22, '&nbsp;داؤد خوراک د سامان وړُونکى ذمه وار کس سره پرېښودو، د جنګ مېدان ته يې منډه کړه، خپلو وروڼو له ورَغلو او سلام يې ورباندې واچولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7134, '1 Samuel 17:23', '1 Samuel', 17, 23, '&nbsp;کله چې هغۀ د هغوئ سره خبرې کولې، نو هغه فلستىے پهلوان جوليت چې د جات وو، د فلستى لښکر نه راووتلو او د مخکښې په شان يې خپله جنګى چغه يې ووهله او دا چغه داؤد واورېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7135, '1 Samuel 17:24', '1 Samuel', 17, 24, '&nbsp;کله چې بنى اِسرائيلو جوليت وليدو، نو هغوئ د يرې نه منډه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7136, '1 Samuel 17:25', '1 Samuel', 17, 25, '&nbsp;هغوئ يو بل ته ووئيل، ”هغۀ ته ګورئ. هغۀ ته غوږ ونيسئ چې هغه وائى چې زما سره جنګ وکړئ. ساؤل بادشاه دا وعده کړې ده چې څوک دے ووژنى نو هغۀ له به يو لوئ اِنعام ورکړى، بادشاه به هغه کس له خپله لور هم ورکوى او د هغۀ خاندان به د محصُول ورکولو نه آزاده وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7137, '1 Samuel 17:26', '1 Samuel', 17, 26, '&nbsp;داؤد د هغه سړو نه تپوس وکړو چې کوم د هغۀ سره نزدې وُو، ”هغه سړى ته به څۀ مِلاو شى چې څوک دا فلستىے ووژنى او بنى اِسرائيليان د دې بې‌عزتۍ نه خلاص کړى؟ ځکه چې دا ناسنته فلستىے څوک دے چې د ژوندى خُدائ پاک لښکر ته وائى چې زما سره جنګ وکړئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7138, '1 Samuel 17:27', '1 Samuel', 17, 27, '&nbsp;نو هغوئ ورته ووئيل چې څوک جوليت ووژنى نو د هغۀ دپاره به دا اِنعام وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7139, '1 Samuel 17:28', '1 Samuel', 17, 28, '&nbsp;د داؤد مشر ورور اِلياب د داؤد خبرې واورېدلې چې د سړو سره يې کولې. هغه داؤد ته سخت غصه شو او ورته يې ووئيل، ”تۀ دلته څۀ کوې؟ ستا د ګډو خيال څوک ساتى چې کومې په بيابان کښې دى؟ ما ته پته ده چې تۀ څومره مغروره يې او ستا په زړۀ کښې څومره فساد دے. تۀ صِرف د جنګ ليدو له راغلے يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7140, '1 Samuel 17:29', '1 Samuel', 17, 29, '&nbsp;داؤد تپوس وکړو، ”نو اوس ما څۀ غلطى وکړه؟ زۀ يو تپوس هم نۀ شم کولے څۀ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7141, '1 Samuel 17:30', '1 Samuel', 17, 30, '&nbsp;هغه د هغۀ نه يو بل سړى ته راوګرځېدو او هم دغه تپوس يې ترې نه وکړو او چې هر ځل يې کولو، نو هم دغه جواب ورته مِلاوېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7142, '1 Samuel 17:31', '1 Samuel', 17, 31, '&nbsp;کله چې هغه خبرې واورېدلے شوې چې کومې داؤد کړې وې، نو هغه سړو دا خبرې د ساؤل په مخکښې هم وکړې، نو داؤد يې راوغوښتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7143, '1 Samuel 17:32', '1 Samuel', 17, 32, '&nbsp;داؤد ساؤل ته وفرمائيل، ”هيڅ څوک هم دې د هغه فلستى په وجه زړۀ نۀ غورزوى، ستا خِدمت کوونکے به لاړ شى او د دې فلستى سره به جنګ وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7144, '1 Samuel 17:33', '1 Samuel', 17, 33, '&nbsp;ساؤل داؤد ته ووئيل، ”تۀ به د هغۀ سره څنګه وجنګېږې؟ ځکه چې تۀ هلک يې او هغه د ټول عُمر فوجى دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7145, '1 Samuel 17:34', '1 Samuel', 17, 34, '&nbsp;خو داؤد ساؤل ته وفرمائيل، ”ستا خِدمت کوونکے د خپل پلار د ګډو خيال ساتى. کله هم چې يو زمرے يا مېلو د رَمې نه يو ګډُورے وتښتوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7146, '1 Samuel 17:35', '1 Samuel', 17, 35, '&nbsp;نو زۀ ورپسې ځم، حمله پرې کوم او د هغۀ د خولې نه يې بچ کوم او کۀ هغه ځناور په ما باندې حمله کوى نو د ژامنې نه يې ونيسم، وې وهم او وې وژنم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7147, '1 Samuel 17:36', '1 Samuel', 17, 36, '&nbsp;ستا خِدمت کوونکى ازمرى او مېلوګان دواړه وژلى دى او زۀ به د دې ناسنته فلستى سره هم دغه شان وکړم، کوم چې د ژوندى خُدائ پاک د لښکر مخالفت کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7148, '1 Samuel 17:37', '1 Samuel', 17, 37, '&nbsp;مالِک خُدائ زۀ د ازمرى د پنجې نه او د مېلو د پنجې نه بچ کړے يم، او هغه به مې د دې فلستى د لاس نه هم بچ کړى.“ نو ساؤل داؤد ته ووئيل، ”ځه، مالِک خُدائ دې مل شه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7149, '1 Samuel 17:38', '1 Samuel', 17, 38, '&nbsp;بيا ساؤل داؤد له خپل جنګى لِباس ورکړو، د زېړو جنګى ټوپۍ، کومه يې چې د داؤد په سر کېښوده او يوه زغره يې هم ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7150, '1 Samuel 17:39', '1 Samuel', 17, 39, '&nbsp;داؤد د ساؤل تُوره په خپلې زغرې پورې وتړله او د روانېدو کوشش يې وکړو، خو هغه نۀ شو تلے، ځکه چې هغۀ دا څيزونه نۀ اغوستل. هغۀ ساؤل ته وفرمائيل، ”د دې څيزونو سره زۀ جنګ نۀ شم کولے. زۀ د دې سره عادت نۀ يم.“ نو هغه يې لرې کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7151, '1 Samuel 17:40', '1 Samuel', 17, 40, '&nbsp;هغۀ په لاس کښې خپله امسا واخستله او بيا د ولې پينځۀ هوار کاڼى يې خوښ کړل او په خپله بوجۍ کښې يې واچول. لينده يې په لاس کښې وه او هغه فلستى له ورَغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7152, '1 Samuel 17:41', '1 Samuel', 17, 41, '&nbsp;هغه فلستىے د داؤد طرف ته روان شو، د هغۀ ډال وړونکے د هغۀ نه مخکښې روان وو. هغه نور هم ورنزدې کېدو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7153, '1 Samuel 17:42', '1 Samuel', 17, 42, '&nbsp;او کله چې هغه داؤد له ښۀ ورنزدې شو، نو هغۀ پورې ورله خندا ورغله ځکه چې هغه سور سپين او ښائسته هلک وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7154, '1 Samuel 17:43', '1 Samuel', 17, 43, '&nbsp;هغۀ داؤد ته ووئيل، ”زۀ سپے يم څۀ، چې تۀ په ما پسې د امسا سره راغلې؟“ او هغۀ داؤد باندې د خپلو معبودانو لعنت وئيلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7155, '1 Samuel 17:44', '1 Samuel', 17, 44, '&nbsp;هغۀ داؤد ته ووئيل، ”راشه. چې زۀ ستا غوښه مارغانو او ځنګلى ځناورو له ورکړم چې وې خورى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7156, '1 Samuel 17:45', '1 Samuel', 17, 45, '&nbsp;داؤد جواب ورکړو، ”تۀ ما له د تُورې، نېزې او وړې نېزې سره راروان يې، خو زۀ ستا خِلاف د ربُ الافواج د نوم سره درځم، چې د بنى اِسرائيلو د لښکر خُدائ پاک دے، چې تا د هغۀ مخالفت کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7157, '1 Samuel 17:46', '1 Samuel', 17, 46, '&nbsp;دا هغه ورځ ده چې مالِک خُدائ به دې ما له په لاس کښې راکړى، زۀ به تا له شکست درکړم او سر به درنه وغورزوم. او زۀ به د فلستى فوجيانو لاشونه مارغانو او ځناورو ته واچوم چې وې خورى. نو چې ټولې دُنيا ته پته ولګى چې د بنى اِسرائيلو خُدائ پاک شته،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7158, '1 Samuel 17:47', '1 Samuel', 17, 47, '&nbsp;او دلته به هر چا ته پته ولګى چې مالِک خُدائ ته د خپلو خلقو بچ کولو دپاره د تُورو او وړو نېزو ضرورت نشته. ځکه چې دا د مالِک خُدائ جنګ دے او هغه به تاسو ټول مونږ ته حواله کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7159, '1 Samuel 17:48', '1 Samuel', 17, 48, '&nbsp;جوليت د داؤد طرف ته يو ځل بيا روان شو او داؤد زر زر د فلستيانو د جنګ صفونو ته ورمنډه کړه چې د هغۀ سره مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7160, '1 Samuel 17:49', '1 Samuel', 17, 49, '&nbsp;هغۀ خپلې بوجۍ ته لاس وردننه کړو او يو کاڼے يې ترې نه راوويستو، په لينده يې جوليت په سر باندې وويشتو. کاڼے د هغۀ په تندى کښې وردننه شو او هغه پړمخې په زمکه راپرېوتو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7161, '1 Samuel 17:50', '1 Samuel', 17, 50, '&nbsp;نو داسې داؤد بغېر د تُورې نه، د يوې ليندې او يو کاڼى سره جوليت له شکست ورکړو او وې وژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7162, '1 Samuel 17:51', '1 Samuel', 17, 51, '&nbsp;داؤد هغۀ له ورمنډه کړه، دپاسه پرې ودرېدو، د جوليت تُوره يې د کاش نه راوُويسته، سر يې ترې نه پرې کړو او هغه يې مړ کړو. کله چې فلستيانو وليدل چې د هغوئ پهلوان مړ شو، نو هغوئ منډه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7163, '1 Samuel 17:52', '1 Samuel', 17, 52, '&nbsp;د اِسرائيل او يهوداه سړو چغې وهلې او په هغوئ پسې يې منډې وهلې، د جات او عقرون د دروازو پورې ورپسې وُو. فلستى زخميان تر جات او عقرون پورې په هغه لاره غورزېدل چې کومه شعريم ته ځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7164, '1 Samuel 17:53', '1 Samuel', 17, 53, '&nbsp;کله چې بنى اِسرائيل په فلستيانو پسې نور نۀ تلل او ترې نه راواپس شول، نو د هغوئ خېمې يې لوټ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7165, '1 Samuel 17:54', '1 Samuel', 17, 54, '&nbsp;داؤد د جوليت سر واخستو او يروشلم ته يې يوړو، خو هغۀ د جوليت وسله په خپله خېمه کښې کېښوده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7166, '1 Samuel 17:55', '1 Samuel', 17, 55, '&nbsp;کله چې ساؤل وليدل چې داؤد د جوليت سره جنګ له روان دے، نو هغۀ د ابنير نه تپوس وکړو، چې کوم يې د خپل لښکر مشر وو، ”ابنيره، دا د چا زوئ دے؟“ ابنير ورته ووئيل، ”بادشاه سلامت، ما ته هيڅ پته نشته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7167, '1 Samuel 17:56', '1 Samuel', 17, 56, '&nbsp;نو ساؤل حُکم ورکړو، ”لاړ شه او معلوم يې کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7168, '1 Samuel 17:57', '1 Samuel', 17, 57, '&nbsp;کله چې داؤد د جوليت وژلو نه پس خېمو ته راواپس شو، نو ابنير هغه ساؤل له بوتلو. داؤد د جوليت سر په لاس کښې روان کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7169, '1 Samuel 17:58', '1 Samuel', 17, 58, '&nbsp;ساؤل ترې نه تپوس وکړو، ”زلميه، تۀ د چا زوئ يې؟“ داؤد ورته وفرمائيل، ”زۀ د بيت‌لحم نه ستا د خِدمت کوونکى يَسى زوئ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7170, '1 Samuel 18:1', '1 Samuel', 18, 1, '&nbsp;کله چې داؤد خبرې ختمې کړې نو هغه د بادشاه زوئ يونتن سره مِلاو شو. هغه د داؤد خوږ دوست جوړ شو او د هغۀ سره يې د خپل ځان په شان مينه کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7171, '1 Samuel 18:2', '1 Samuel', 18, 2, '&nbsp;ساؤل هم د هغه ورځې نه داؤد ځان سره وساتلو او هغه يې د پلار کور ته نۀ پرېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7172, '1 Samuel 18:3', '1 Samuel', 18, 3, '&nbsp;يونتن داؤد له د دوستۍ پوخ لاس ورکړو ځکه چې د هغۀ سره يې د خپل ځان په شان مينه لرله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7173, '1 Samuel 18:4', '1 Samuel', 18, 4, '&nbsp;هغۀ چې کومه چُوغه اغوستله هغه يې وويستله او داؤد له يې ورکړه، خپله زغره، تُوره، لينده او خپله پټۍ يې هم ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7174, '1 Samuel 18:5', '1 Samuel', 18, 5, '&nbsp;ساؤل به چې داؤد په هر کار پسې هم ولېږلو، نو هغه به يې په ښۀ طريقه سر ته رسولو. نو ساؤل هغه په خپل لښکر کښې آفسر جوړ کړو. په دې باندې د ساؤل ټول آفسران او سړى خوشحاله شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7175, '1 Samuel 18:6', '1 Samuel', 18, 6, '&nbsp;کله چې داؤد د جوليت د وژلو نه پس واپس راتلو او فوجيان کورونو ته واپس راروان وُو، نو د بنى اِسرائيلو هر ښار نه د ساؤل بادشاه سره مِلاوېدو دپاره ښځې بهر راووتلې. هغوئ د خوشحالۍ سندرې وئيلې، ګډېدې او بينجو او تمبل يې غږول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7176, '1 Samuel 18:7', '1 Samuel', 18, 7, '&nbsp;په سندرو کښې ښځو وئيل، ”ساؤل زرګونه وژلى دى، خو داؤد يو په لس د هغې نه زيات وژلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7177, '1 Samuel 18:8', '1 Samuel', 18, 8, '&nbsp;ساؤل په دې خفه شو او سخت غصه شو. هغۀ ووئيل، ”هغوئ د داؤد دپاره د لسو زرګونو دعوىٰ کړې ده، خو زما دپاره صِرف د زرګونو دعوىٰ، هغوئ به بيا داؤد بادشاه کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7178, '1 Samuel 18:9', '1 Samuel', 18, 9, '&nbsp;نو د هغه ورځې نه هغۀ داؤد ته د شک په نظر کتل شروع کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7179, '1 Samuel 18:10', '1 Samuel', 18, 10, '&nbsp;په ورپسې ورځ د خُدائ پاک د طرف نه يو پېرى ساؤل ناڅاپه ونيولو، نو هغۀ په خپل کور کښې د ليونى په شان چغې وهلې. داؤد بينجو غږوله لکه چې هغۀ به هره ورځ غږوله او ساؤل نېزه په لاس کښې نيولې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7180, '1 Samuel 18:11', '1 Samuel', 18, 11, '&nbsp;ساؤل د ځان سره ووئيل، ”زۀ به هغه د دېوال سره ونښلوم او هغۀ دوه ځلې نېزه ورګزار کړه، خو داؤد هر ځل ځان بچ کولو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7181, '1 Samuel 18:12', '1 Samuel', 18, 12, '&nbsp;ساؤل د داؤد نه يرېدو ځکه چې هغه مالِک خُدائ پرېښے وو او د داؤد مل وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7182, '1 Samuel 18:13', '1 Samuel', 18, 13, '&nbsp;نو ساؤل هغه د ځان نه لرې کړو او د زرو سړو مشر يې جوړ کړو. داؤد په جنګ کښې د سړو مشرى کوله', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7183, '1 Samuel 18:14', '1 Samuel', 18, 14, '&nbsp;او هغه په هر کار کښې کاميابېدو، ځکه چې مالِک خُدائ د هغۀ مل وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7184, '1 Samuel 18:15', '1 Samuel', 18, 15, '&nbsp;ساؤل د داؤد کاميابى وليده او نور هم ترې ويرېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7185, '1 Samuel 18:16', '1 Samuel', 18, 16, '&nbsp;خو په اِسرائيل او يهوداه کښې هر يو کس د داؤد سره مينه کوله ځکه چې هغه يو ښۀ مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7186, '1 Samuel 18:17', '1 Samuel', 18, 17, '&nbsp;بيا ساؤل داؤد ته ووئيل، ”دا زما مشره لور ميرب ده. دا به زۀ تا ته په دې شرط وادۀ کړم چې تۀ به د يو تکړه او وفادار فوجى په شان زما خِدمت کوې او د مالِک خُدائ جنګونه به کوې.“ د ساؤل خيال دا وو چې داؤد به پخپله لاس نۀ وژنى بلکې په فلستيانو باندې به يې ووژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7187, '1 Samuel 18:18', '1 Samuel', 18, 18, '&nbsp;داؤد ورته وفرمائيل، ”زۀ څوک يم او زما د خاندان څۀ حيثيت دے چې زۀ د بادشاه زوم جوړ شم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7188, '1 Samuel 18:19', '1 Samuel', 18, 19, '&nbsp;خو چې کله هغه وخت راغلو چې ميرب داؤد له ورکړى، نو هغه يې يو بل محولاتى سړى له ورکړه چې نوم يې عدرى‌اېل وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7189, '1 Samuel 18:20', '1 Samuel', 18, 20, '&nbsp;خو د ساؤل لور ميکل په داؤد مئينه شوه او کله چې ساؤل ترې نه خبر شو نو هغه خوشحاله شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7190, '1 Samuel 18:21', '1 Samuel', 18, 21, '&nbsp;هغۀ د ځان سره ووئيل، ”زۀ به ميکل داؤد له ورکړم، زۀ هغۀ له دا د دې دپاره ورکوم چې د هغۀ دپاره يو دام جوړ شى او فلستيان يې ووژنى.“ نو ساؤل په دوېم ځل داؤد ته ووئيل، ”تۀ به زما زوم شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7191, '1 Samuel 18:22', '1 Samuel', 18, 22, '&nbsp;هغۀ خپلو آفسرانو ته حُکم وکړو چې د داؤد سره په پرده کښې خبرې وکړى او ورته ووائى، ”بادشاه ستا نه خوشحاله دے او د هغۀ ټول آفسران تا خوښوى، دا ستا دپاره يو ښۀ وخت دے چې د هغۀ لور وادۀ کړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7192, '1 Samuel 18:23', '1 Samuel', 18, 23, '&nbsp;نو هغوئ داؤد ته ووئيل او هغۀ جواب ورکړو، ”د بادشاه زوم جوړېدل دا يوه لويه د عزت خبره ده، دا زما په شان غريب او کمزورى کس دپاره ډېره لويه خبره ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7193, '1 Samuel 18:24', '1 Samuel', 18, 24, '&nbsp;چې داؤد څۀ فرمائيلى وُو آفسرانو هغه ساؤل ته ووئيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7194, '1 Samuel 18:25', '1 Samuel', 18, 25, '&nbsp;او ساؤل هغوئ له حُکم ورکړو چې داؤد ته ووايئ، ”بادشاه ستا نه د ناوې دا قيمت غواړى چې تۀ صِرف د سلو وژلو شوو فلستيانو سړو د سنتېدو څرمن راوړې، دا به د هغۀ د دشمنانو نه بدل اخستل وى.“ (نو دا د ساؤل منصوبه وه چې فلستيان داؤد ووژنى.)', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7195, '1 Samuel 18:26', '1 Samuel', 18, 26, '&nbsp;د ساؤل آفسرانو داؤد ته هغه څۀ ووئيل چې څۀ ساؤل فرمائيلى وُو او داؤد په دې خوشحاله وو چې د بادشاه زوم به جوړ شى. د وادۀ د ورځې مقررېدو نه مخکښې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7196, '1 Samuel 18:27', '1 Samuel', 18, 27, '&nbsp;داؤد او د هغۀ سړى لاړل او دوه سوه فلستيان يې ووژل. هغۀ د هغوئ د سنتېدو څرمن راوړه او ټول په شمېر کښې پوره وُو، د دې دپاره چې زوم يې جوړ شى. نو ساؤل خپله لور داؤد له ورکړه چې وادۀ يې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7197, '1 Samuel 18:28', '1 Samuel', 18, 28, '&nbsp;ساؤل ته صفا پته ولګېده چې مالِک خُدائ د داؤد مل دے او دا چې د هغۀ لور ميکل هم ورسره مينه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7198, '1 Samuel 18:29', '1 Samuel', 18, 29, '&nbsp;نو هغه د داؤد نه نور هم ويرېدو او چې ترڅو پورې ژوندے وو نو هغه يې دشمن وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7199, '1 Samuel 18:30', '1 Samuel', 18, 30, '&nbsp;د فلستيانو لښکرې به راتلې او جنګ به يې کولو او داؤد به د ساؤل د نورو آفسرانو نه په جنګ کښې زيات کامياب وو. نو په دې وجه داؤد ښۀ مشهور شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7200, '1 Samuel 19:1', '1 Samuel', 19, 1, '&nbsp;بيا ساؤل خپل زوئ يونتن او خپلو ټولو درباريانو ته ووئيل چې ما د داؤد د قتلولو منصوبه جوړه کړې ده خو يونتن د داؤد نه ډېر خوشحاله وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');